#use this script to decompress graphics data into data readable by graphics viewers/editors like YY-CHR.
#input .bin via a command line argument generated by extraction script, and this script will generate a workable .bin, which will be placed in DecompressedOutput folder.

import sys
import os

DecompressFile = sys.argv[1]
DecompressFolder = "DecompressedOutput"
DecompressedFile = DecompressFolder+"/"+os.path.basename(DecompressFile).split('/')[-1]

def extract_byteToInt(byte):
    byte_to_int = int.from_bytes(byte, byteorder='little')
    return byte_to_int

try:
    os.mkdir(DecompressFolder)                #generate DecompressFolder folder from script's position, I think
except:
    pass

with open(DecompressFile, "rb") as inFile, open(DecompressedFile, "wb") as outFile:
    key = inFile.read(1) #the first byte of any DuckTales Game Boy graphic files is a key byte
    while 1:
        currentByte = inFile.read(1)
        if currentByte == key:
            #check immediate next byte
            nextByte = extract_byteToInt(inFile.read(1))
            if nextByte == 0:
                break               #we're done!
            else:
                #next byte is the amount of times we loop the next next byte.
                repeatByte = inFile.read(1)
                for i in range(0,nextByte):
                    outFile.write(repeatByte)
        else:
            outFile.write(currentByte)